// Deterministic, weighted perceptual clustering; avoid spending palette slots on edge shades.
function lab(r,g,b){const lin=v=>{v/=255;return v>.04045?((v+.055)/1.055)**2.4:v/12.92;};r=lin(r);g=lin(g);b=lin(b);const f=v=>v>.008856?Math.cbrt(v):7.787*v+16/116;const x=f((.4124564*r+.3575761*g+.1804375*b)/.95047),y=f(.2126729*r+.7151522*g+.072175*b),z=f((.0193339*r+.119192*g+.9503041*b)/1.08883);return [116*y-16,500*(x-y),200*(y-z)];}
const distance=(a,b)=>(a[0]-b[0])**2+(a[1]-b[1])**2+(a[2]-b[2])**2;
function quantize(pixels,count){const bins=new Map();for(let i=0;i<pixels.length;i+=4){const r=pixels[i],g=pixels[i+1],b=pixels[i+2],key=(r>>3)*1024+(g>>3)*32+(b>>3);let h=bins.get(key);if(!h){h={n:0,r:0,g:0,b:0,key};bins.set(key,h);}h.n++;h.r+=r;h.g+=g;h.b+=b;}
 const points=[...bins.values()].map(h=>({...h,r:h.r/h.n,g:h.g/h.n,b:h.b/h.n})).sort((a,b)=>b.n-a.n||a.key-b.key);for(const p of points)p.lab=lab(p.r,p.g,p.b);const centers=[points[0].lab.slice()];while(centers.length<Math.min(count,points.length)){let best=null,score=-1;for(const p of points){const d=Math.min(...centers.map(c=>distance(p.lab,c)));const s=d*Math.sqrt(p.n);if(s>score){score=s;best=p;}}if(score<1e-8)break;centers.push(best.lab.slice());}
 let groups;for(let iteration=0;iteration<16;iteration++){groups=centers.map(()=>({n:0,l:[0,0,0],members:[]}));for(const p of points){let idx=0,min=Infinity;centers.forEach((c,i)=>{const d=distance(p.lab,c);if(d<min){min=d;idx=i;}});const g=groups[idx];g.n+=p.n;for(let k=0;k<3;k++)g.l[k]+=p.lab[k]*p.n;g.members.push(p);}let shift=0;groups.forEach((g,i)=>{if(g.n){const c=g.l.map(v=>v/g.n);shift+=distance(c,centers[i]);centers[i]=c;}});if(shift<.01)break;}
 // Use the most common source shade per cluster, rather than muddy averages of anti-aliasing.
 const palette=groups.filter(g=>g.n).map(g=>{const p=g.members.reduce((a,b)=>a.n>=b.n?a:b);return {r:Math.round(p.r),g:Math.round(p.g),b:Math.round(p.b),a:255};});
 const lookup=new Map();for(const p of points){let idx=0,min=Infinity;palette.forEach((c,i)=>{const d=distance(p.lab,lab(c.r,c.g,c.b));if(d<min){min=d;idx=i;}});lookup.set(p.key,idx);}const labels=new Uint8Array(pixels.length/4);for(let i=0;i<labels.length;i++)labels[i]=lookup.get((pixels[i*4]>>3)*1024+(pixels[i*4+1]>>3)*32+(pixels[i*4+2]>>3));return {palette,labels};}
function cleanLabels(labels,width,height){const out=labels.slice();for(let y=1;y<height-1;y++)for(let x=1;x<width-1;x++){const i=y*width+x;const counts=new Map();for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const c=labels[i+dy*width+dx];counts.set(c,(counts.get(c)||0)+1);}for(const [c,n]of counts)if(n>=6)out[i]=c;}return out;}
